package com.company.platform.integration.domain;import java.time.Instant;import java.util.*;public record IntegrationJob(UUID id,UUID tenantId,UUID connectorId,String executionType,String status,Instant startedAt,Instant finishedAt,UUID correlationId,int retryCount,Instant createdAt){public IntegrationJob{if(id==null||tenantId==null||connectorId==null||executionType==null||status==null||correlationId==null||createdAt==null)throw new IllegalArgumentException("invalid integration job");}public static IntegrationJob create(UUID t,UUID c,String e){return new IntegrationJob(UUID.randomUUID(),t,c,e,"PENDING",null,null,UUID.randomUUID(),0,Instant.now());}public IntegrationJob start(){return new IntegrationJob(id,tenantId,connectorId,executionType,"RUNNING",Instant.now(),finishedAt,correlationId,retryCount,createdAt);}public IntegrationJob complete(){return new IntegrationJob(id,tenantId,connectorId,executionType,"COMPLETED",startedAt,Instant.now(),correlationId,retryCount,createdAt);}public IntegrationJob fail(){return new IntegrationJob(id,tenantId,connectorId,executionType,"FAILED",startedAt,Instant.now(),correlationId,retryCount+1,createdAt);}public IntegrationJob cancel(){return new IntegrationJob(id,tenantId,connectorId,executionType,"CANCELLED",startedAt,Instant.now(),correlationId,retryCount,createdAt);}}
